import * as React from 'react';
import { K8sStatus } from '@openshift/dynamic-plugin-sdk-utils';
import { getServingRuntimeContext, listServingRuntimes, useAccessReview } from '#~/api';
import { AccessReviewResourceAttributes, KnownLabels, ServingRuntimeKind } from '#~/k8sTypes';
import useModelServingEnabled from '#~/pages/modelServing/useModelServingEnabled';
import useFetch, {
  FetchOptions,
  FetchStateObject,
  FetchStateCallbackPromise,
  NotReadyError,
} from '#~/utilities/useFetch';
import { ListWithNonDashboardPresence } from '#~/types';
import { DEFAULT_LIST_WITH_NON_DASHBOARD_PRESENCE } from '#~/utilities/const';

const accessReviewResource: AccessReviewResourceAttributes = {
  group: 'serving.kserve.io',
  resource: 'servingruntimes',
  verb: 'list',
};

const useServingRuntimes = (
  namespace?: string,
  notReady?: boolean,
  fetchOptions?: Partial<FetchOptions>,
): FetchStateObject<ListWithNonDashboardPresence<ServingRuntimeKind>> => {
  const modelServingEnabled = useModelServingEnabled();

  const [allowCreate, rbacLoaded] = useAccessReview({
    ...accessReviewResource,
  });

  const callback = React.useCallback<
    FetchStateCallbackPromise<ListWithNonDashboardPresence<ServingRuntimeKind>>
  >(
    async (opts) => {
      if (!modelServingEnabled) {
        return Promise.reject(new NotReadyError('Model serving is not enabled'));
      }

      if (notReady || !rbacLoaded) {
        return Promise.reject(new NotReadyError('Fetch is not ready'));
      }

      const getServingRuntimes = allowCreate ? listServingRuntimes : getServingRuntimeContext;

      try {
        const servingRuntimeList = await getServingRuntimes(namespace, undefined, opts);
        const dashboardServingRuntimes = servingRuntimeList.filter(
          ({ metadata: { labels } }) => labels?.[KnownLabels.DASHBOARD_RESOURCE] === 'true',
        );
        return {
          items: dashboardServingRuntimes,
          hasNonDashboardItems: servingRuntimeList.length > dashboardServingRuntimes.length,
        };
      } catch (e) {
        // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
        if ((e as { statusObject?: K8sStatus }).statusObject?.code === 404) {
          throw new Error('Model serving is not properly configured.');
        }
        throw e;
      }
    },
    [namespace, modelServingEnabled, notReady, rbacLoaded, allowCreate],
  );

  return useFetch(callback, DEFAULT_LIST_WITH_NON_DASHBOARD_PRESENCE, {
    initialPromisePurity: true,
    ...fetchOptions,
  });
};

export default useServingRuntimes;

import * as React from 'react';
import { getSecretsByLabel } from '#~/api';
import { SecretKind } from '#~/k8sTypes';
import useModelServingEnabled from '#~/pages/modelServing/useModelServingEnabled';
import useFetch, { FetchOptions, FetchStateObject, NotReadyError } from '#~/utilities/useFetch';
import { LABEL_SELECTOR_DASHBOARD_RESOURCE } from '#~/const';

const useServingRuntimeSecrets = (
  namespace?: string,
  fetchOptions?: Partial<FetchOptions>,
): FetchStateObject<SecretKind[]> => {
  const modelServingEnabled = useModelServingEnabled();

  const fetchSecrets = React.useCallback(() => {
    if (!namespace) {
      return Promise.reject(new NotReadyError('No namespace'));
    }

    if (!modelServingEnabled) {
      return Promise.reject(new NotReadyError('Model serving is not enabled'));
    }

    return getSecretsByLabel(LABEL_SELECTOR_DASHBOARD_RESOURCE, namespace);
  }, [namespace, modelServingEnabled]);

  return useFetch<SecretKind[]>(fetchSecrets, [], fetchOptions);
};

export default useServingRuntimeSecrets;

import * as _ from 'lodash-es';
import {
  k8sCreateResource,
  k8sDeleteResource,
  k8sGetResource,
  k8sListResource,
  K8sStatus,
  k8sUpdateResource,
  k8sPatchResource,
} from '@openshift/dynamic-plugin-sdk-utils';
import { InferenceServiceModel, PodModel } from '#~/api/models';
import {
  InferenceServiceKind,
  K8sAPIOptions,
  KnownLabels,
  PodKind,
  DeploymentMode,
} from '#~/k8sTypes';
import { CreatingInferenceServiceObject } from '#~/pages/modelServing/screens/types';
import { applyK8sAPIOptions } from '#~/api/apiMergeUtils';
import { parseCommandLine } from '#~/api/k8s/utils';
import { getModelServingProjects } from '#~/api';

const applyAuthToInferenceService = (
  inferenceService: InferenceServiceKind,
  tokenAuth: boolean,
) => {
  const updateInferenceService = structuredClone(inferenceService);
  if (!updateInferenceService.metadata.annotations) {
    updateInferenceService.metadata.annotations = {};
  }
  delete updateInferenceService.metadata.annotations['security.opendatahub.io/enable-auth'];

  if (tokenAuth) {
    updateInferenceService.metadata.annotations['security.opendatahub.io/enable-auth'] = 'true';
  }

  return updateInferenceService;
};

const applyRoutingToInferenceService = (
  inferenceService: InferenceServiceKind,
  externalRoute: boolean,
) => {
  const updateInferenceService = structuredClone(inferenceService);
  if (!updateInferenceService.metadata.labels) {
    updateInferenceService.metadata.labels = {};
  }
  delete updateInferenceService.metadata.labels['networking.knative.dev/visibility'];
  delete updateInferenceService.metadata.labels['networking.kserve.io/visibility'];

  if (externalRoute) {
    updateInferenceService.metadata.labels['networking.kserve.io/visibility'] = 'exposed';
  }

  return updateInferenceService;
};

export const assembleInferenceService = (
  data: CreatingInferenceServiceObject,
  secretKey?: string,
  editName?: string,
  inferenceService?: InferenceServiceKind,
  isStorageNeeded?: boolean,
  applyHardwareProfile?: (resource: InferenceServiceKind) => InferenceServiceKind,
): InferenceServiceKind => {
  const {
    storage,
    format,
    servingRuntimeName,
    project,
    maxReplicas,
    minReplicas,
    imagePullSecrets,
    tokenAuth,
    externalRoute,
    servingRuntimeArgs,
    servingRuntimeEnvVars,
  } = data;
  const name = editName || data.k8sName;
  const { path, dataConnection, uri } = storage;
  const dataConnectionKey = secretKey || dataConnection;

  const nonEmptyArgs = servingRuntimeArgs?.filter(Boolean) || [];
  // Ensure that we properly handle separating args
  const splitArgs: string[] = nonEmptyArgs.flatMap(parseCommandLine);
  const nonEmptyEnvVars = servingRuntimeEnvVars?.filter((ev) => ev.name) || [];

  let updatedInferenceService: InferenceServiceKind = inferenceService
    ? { ...inferenceService }
    : {
        apiVersion: 'serving.kserve.io/v1beta1',
        kind: 'InferenceService',
        metadata: {
          name,
          namespace: project,
          annotations: {},
          labels: {},
        },
        spec: {
          predictor: {
            model: {},
          },
        },
      };

  const annotations = { ...updatedInferenceService.metadata.annotations };

  annotations['openshift.io/display-name'] = data.name.trim();
  annotations['serving.kserve.io/deploymentMode'] = DeploymentMode.RawDeployment;
  const labels = { ...updatedInferenceService.metadata.labels, ...data.labels };
  labels[KnownLabels.DASHBOARD_RESOURCE] = 'true';

  updatedInferenceService.metadata.annotations = annotations;
  updatedInferenceService.metadata.labels = labels;

  const spec = { ...updatedInferenceService.spec };
  const predictor = { ...spec.predictor };
  predictor.minReplicas = minReplicas;
  predictor.maxReplicas = maxReplicas;
  predictor.imagePullSecrets = imagePullSecrets;

  const model = { ...predictor.model };
  model.modelFormat = {
    name: format.name,
    ...(format.version && { version: format.version }),
  };
  model.runtime = servingRuntimeName;

  if (uri) {
    model.storageUri = uri;
    delete model.storage;
  } else {
    delete model.storageUri;
    model.storage = {
      key: dataConnectionKey,
      path,
    };
  }

  model.args = splitArgs;
  model.env = nonEmptyEnvVars;

  predictor.model = model;

  spec.predictor = predictor;

  updatedInferenceService.spec = spec;

  updatedInferenceService = applyAuthToInferenceService(updatedInferenceService, tokenAuth);
  updatedInferenceService = applyRoutingToInferenceService(updatedInferenceService, externalRoute);
  if (applyHardwareProfile) {
    updatedInferenceService = applyHardwareProfile(updatedInferenceService);
  }

  // If storage is not needed, remove storage from the inference service
  if (isStorageNeeded !== undefined && !isStorageNeeded) {
    delete updatedInferenceService.spec.predictor.model?.storage;
  }

  return updatedInferenceService;
};

export const listInferenceService = (
  namespace?: string,
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<InferenceServiceKind[]> => {
  const queryOptions = {
    ...(namespace && { ns: namespace }),
    ...(labelSelector && { queryParams: { labelSelector } }),
  };
  return k8sListResource<InferenceServiceKind>(
    applyK8sAPIOptions(
      {
        model: InferenceServiceModel,
        queryOptions,
      },
      opts,
    ),
  ).then((listResource) => listResource.items);
};

export const listScopedInferenceService = (
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<InferenceServiceKind[]> =>
  getModelServingProjects(opts).then((projects) =>
    Promise.all(
      projects.map((project) => listInferenceService(project.metadata.name, labelSelector, opts)),
    ).then((fetchedListInferenceService) =>
      _.flatten(
        fetchedListInferenceService.map((projectInferenceServices) =>
          _.uniqBy(projectInferenceServices, (is) => is.metadata.name),
        ),
      ),
    ),
  );

export const getInferenceServiceContext = (
  namespace?: string,
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<InferenceServiceKind[]> => {
  if (namespace) {
    return listInferenceService(namespace, labelSelector, opts);
  }
  return listScopedInferenceService(labelSelector, opts);
};

export const getInferenceService = (
  name: string,
  namespace: string,
  opts?: K8sAPIOptions,
): Promise<InferenceServiceKind> =>
  k8sGetResource<InferenceServiceKind>(
    applyK8sAPIOptions(
      {
        model: InferenceServiceModel,
        queryOptions: { name, ns: namespace },
      },
      opts,
    ),
  );

export const getInferenceServicePods = (
  name: string,
  namespace: string,
  opts?: K8sAPIOptions,
): Promise<PodKind[]> =>
  k8sListResource<PodKind>(
    applyK8sAPIOptions(
      {
        model: PodModel,
        queryOptions: {
          ns: namespace,
          queryParams: {
            labelSelector: `serving.kserve.io/inferenceservice=${name}`,
          },
        },
      },
      opts,
    ),
  ).then((listResource) => listResource.items);

export const createInferenceService = (
  data: CreatingInferenceServiceObject,
  secretKey?: string,
  applyHardwareProfile?: (resource: InferenceServiceKind) => InferenceServiceKind,
  dryRun = false,
  isStorageNeeded?: boolean,
): Promise<InferenceServiceKind> => {
  const inferenceService = assembleInferenceService(
    data,
    secretKey,
    undefined,
    undefined,
    isStorageNeeded,
    applyHardwareProfile,
  );
  return k8sCreateResource<InferenceServiceKind>(
    applyK8sAPIOptions(
      {
        model: InferenceServiceModel,
        resource: inferenceService,
      },
      { dryRun },
    ),
  );
};

export const updateInferenceService = (
  data: CreatingInferenceServiceObject,
  existingData: InferenceServiceKind,
  secretKey?: string,
  applyHardwareProfile?: (resource: InferenceServiceKind) => InferenceServiceKind,
  dryRun = false,
  isStorageNeeded?: boolean,
): Promise<InferenceServiceKind> => {
  const inferenceService = assembleInferenceService(
    data,
    secretKey,
    existingData.metadata.name,
    existingData,
    isStorageNeeded,
    applyHardwareProfile,
  );

  return k8sUpdateResource<InferenceServiceKind>(
    applyK8sAPIOptions(
      {
        model: InferenceServiceModel,
        resource: inferenceService,
      },
      { dryRun },
    ),
  );
};

export const deleteInferenceService = (
  name: string,
  namespace: string,
  opts?: K8sAPIOptions,
): Promise<K8sStatus> =>
  k8sDeleteResource<InferenceServiceKind, K8sStatus>(
    applyK8sAPIOptions(
      {
        model: InferenceServiceModel,
        queryOptions: { name, ns: namespace },
      },
      opts,
    ),
  );

export const patchInferenceServiceStoppedStatus = (
  inferenceService: InferenceServiceKind,
  stoppedStatus: 'true' | 'false',
): Promise<InferenceServiceKind> =>
  k8sPatchResource({
    model: InferenceServiceModel,
    queryOptions: {
      name: inferenceService.metadata.name,
      ns: inferenceService.metadata.namespace,
    },
    patches: [
      {
        op: 'add',
        path: '/metadata/annotations/serving.kserve.io~1stop',
        value: stoppedStatus,
      },
    ],
  });

import * as _ from 'lodash-es';
import {
  k8sCreateResource,
  k8sDeleteResource,
  k8sGetResource,
  k8sListResource,
  k8sUpdateResource,
} from '@openshift/dynamic-plugin-sdk-utils';
import { ServingRuntimeModel } from '#~/api/models';
import {
  K8sAPIOptions,
  ServingContainer,
  ServingRuntimeAnnotations,
  ServingRuntimeKind,
} from '#~/k8sTypes';
import {
  CreatingServingRuntimeObject,
  SupportedModelFormatsInfo,
} from '#~/pages/modelServing/screens/types';
import { getModelServingRuntimeName } from '#~/pages/modelServing/utils';
import { getDisplayNameFromK8sResource, translateDisplayNameForK8s } from '#~/concepts/k8s/utils';
import { applyK8sAPIOptions } from '#~/api/apiMergeUtils';
import { getModelServingProjects } from '#~/api/k8s/projects';
import { getshmVolume, getshmVolumeMount } from '#~/api/k8s/utils';

export const assembleServingRuntime = (
  data: CreatingServingRuntimeObject,
  namespace: string,
  servingRuntime: ServingRuntimeKind,
  isCustomServingRuntimesEnabled: boolean,
  isEditing?: boolean,
): ServingRuntimeKind => {
  const {
    name: displayName,
    k8sName,
    externalRoute,
    tokenAuth,
    imageName,
    supportedModelFormatsInfo,
    scope,
  } = data;
  const createName = isCustomServingRuntimesEnabled
    ? k8sName || translateDisplayNameForK8s(displayName)
    : getModelServingRuntimeName(namespace);
  const updatedServingRuntime = { ...servingRuntime };

  const annotations: ServingRuntimeAnnotations = {
    ...updatedServingRuntime.metadata.annotations,
  };

  if (externalRoute) {
    annotations['enable-route'] = 'true';
  } else {
    delete annotations['enable-route'];
  }
  if (tokenAuth) {
    annotations['enable-auth'] = 'true';
  } else {
    delete annotations['enable-auth'];
  }

  if (scope) {
    annotations['opendatahub.io/serving-runtime-scope'] = scope;
  }

  // Hardware profile annotations are now handled in the InferenceService, not ServingRuntime
  // Legacy accelerator profile support is no longer needed for KServe

  // TODO: Enable GRPC
  if (!isEditing) {
    updatedServingRuntime.metadata = {
      ...updatedServingRuntime.metadata,
      name: createName,
      namespace,
      labels: {
        ...updatedServingRuntime.metadata.labels,
        'opendatahub.io/dashboard': 'true',
      },
      annotations: {
        ...annotations,
        ...(isCustomServingRuntimesEnabled && { 'openshift.io/display-name': displayName.trim() }),
        ...(isCustomServingRuntimesEnabled && {
          'opendatahub.io/template-name': servingRuntime.metadata.name,
        }),
        ...(isCustomServingRuntimesEnabled && {
          'opendatahub.io/template-display-name': getDisplayNameFromK8sResource(servingRuntime),
        }),
      },
    };
  } else {
    updatedServingRuntime.metadata = {
      ...updatedServingRuntime.metadata,
      annotations: {
        ...annotations,
        ...(isCustomServingRuntimesEnabled && { 'openshift.io/display-name': displayName.trim() }),
      },
    };
  }

  // KServe doesn't use replicas (removed ModelMesh logic)
  delete updatedServingRuntime.spec.replicas;

  updatedServingRuntime.spec.containers = servingRuntime.spec.containers.map(
    (container): ServingContainer => {
      const volumeMounts = container.volumeMounts || [];
      if (!volumeMounts.find((volumeMount) => volumeMount.mountPath === '/dev/shm')) {
        volumeMounts.push(getshmVolumeMount());
      }

      const updatedContainer = {
        ...container,
        ...(imageName && { image: imageName }),
      };

      const containerWithoutResources = _.omit(updatedContainer, 'resources');

      // KServe containers don't include resources (removed ModelMesh logic)
      return {
        ...containerWithoutResources,
        volumeMounts,
      };
    },
  );

  if (supportedModelFormatsInfo) {
    const supportedModelFormatsObj: SupportedModelFormatsInfo = {
      name: supportedModelFormatsInfo.name,
      version: supportedModelFormatsInfo.version,
      autoSelect: false,
      priority: 1,
    };

    updatedServingRuntime.spec.supportedModelFormats = [supportedModelFormatsObj];
  }

  // KServe doesn't use tolerations/nodeSelector at ServingRuntime level (removed ModelMesh logic)

  // Volume mount for /dev/shm
  const volumes = updatedServingRuntime.spec.volumes || [];
  if (!volumes.find((volume) => volume.name === 'shm')) {
    volumes.push(getshmVolume('2Gi'));
  }

  updatedServingRuntime.spec.volumes = volumes;

  return updatedServingRuntime;
};

export const listServingRuntimes = (
  namespace?: string,
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<ServingRuntimeKind[]> => {
  const queryOptions = {
    ...(namespace && { ns: namespace }),
    ...(labelSelector && { queryParams: { labelSelector } }),
  };
  return k8sListResource<ServingRuntimeKind>(
    applyK8sAPIOptions(
      {
        model: ServingRuntimeModel,
        queryOptions,
      },
      opts,
    ),
  ).then((listResource) => listResource.items);
};

export const listScopedServingRuntimes = (
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<ServingRuntimeKind[]> =>
  getModelServingProjects(opts).then((projects) =>
    Promise.all(
      projects.map((project) => listServingRuntimes(project.metadata.name, labelSelector, opts)),
    ).then((fetchedListServingRuntimes) =>
      _.uniqBy(_.flatten(fetchedListServingRuntimes), (sr) => sr.metadata.name),
    ),
  );

export const getServingRuntimeContext = (
  namespace?: string,
  labelSelector?: string,
  opts?: K8sAPIOptions,
): Promise<ServingRuntimeKind[]> => {
  if (namespace) {
    return listServingRuntimes(namespace, labelSelector, opts);
  }
  return listScopedServingRuntimes(labelSelector, opts);
};

export const getServingRuntime = (
  name: string,
  namespace: string,
  opts?: K8sAPIOptions,
): Promise<ServingRuntimeKind> =>
  k8sGetResource<ServingRuntimeKind>(
    applyK8sAPIOptions(
      {
        model: ServingRuntimeModel,
        queryOptions: { name, ns: namespace },
      },
      opts,
    ),
  );

export const updateServingRuntime = (options: {
  data: CreatingServingRuntimeObject;
  existingData: ServingRuntimeKind;
  isCustomServingRuntimesEnabled: boolean;
  opts?: K8sAPIOptions;
}): Promise<ServingRuntimeKind> => {
  const { data, existingData, isCustomServingRuntimesEnabled, opts } = options;

  const updatedServingRuntime = assembleServingRuntime(
    data,
    existingData.metadata.namespace,
    existingData,
    isCustomServingRuntimesEnabled,
    true,
  );

  return k8sUpdateResource<ServingRuntimeKind>(
    applyK8sAPIOptions(
      {
        model: ServingRuntimeModel,
        resource: updatedServingRuntime,
      },
      opts,
    ),
  );
};

export const createServingRuntime = (options: {
  data: CreatingServingRuntimeObject;
  namespace: string;
  servingRuntime: ServingRuntimeKind;
  isCustomServingRuntimesEnabled: boolean;
  opts?: K8sAPIOptions;
}): Promise<ServingRuntimeKind> => {
  const { data, namespace, servingRuntime, isCustomServingRuntimesEnabled, opts } = options;
  const assembledServingRuntime = assembleServingRuntime(
    data,
    namespace,
    servingRuntime,
    isCustomServingRuntimesEnabled,
    false,
  );

  return k8sCreateResource<ServingRuntimeKind>(
    applyK8sAPIOptions(
      {
        model: ServingRuntimeModel,
        resource: assembledServingRuntime,
      },
      opts,
    ),
  );
};

