import * as React from 'react';
import { getInferenceServiceContext, listInferenceService, useAccessReview } from '#~/api';
import { AccessReviewResourceAttributes, InferenceServiceKind, KnownLabels } from '#~/k8sTypes';
import { ListWithNonDashboardPresence } from '#~/types';
import useFetch, {
  FetchOptions,
  FetchStateObject,
  FetchStateCallbackPromise,
  NotReadyError,
} from '#~/utilities/useFetch';
import useModelServingEnabled from '#~/pages/modelServing/useModelServingEnabled';
import { DEFAULT_LIST_WITH_NON_DASHBOARD_PRESENCE } from '#~/utilities/const';

const accessReviewResource: AccessReviewResourceAttributes = {
  group: 'serving.kserve.io',
  resource: 'inferenceservices',
  verb: 'list',
};

const useInferenceServices = (
  namespace?: string,
  registeredModelId?: string,
  modelVersionId?: string,
  mrName?: string,
  fetchOptions?: Partial<FetchOptions>,
): FetchStateObject<ListWithNonDashboardPresence<InferenceServiceKind>> => {
  const modelServingEnabled = useModelServingEnabled();

  const [allowCreate, rbacLoaded] = useAccessReview({
    ...accessReviewResource,
  });

  const callback = React.useCallback<
    FetchStateCallbackPromise<ListWithNonDashboardPresence<InferenceServiceKind>>
  >(
    async (opts) => {
      if (!modelServingEnabled) {
        return Promise.reject(new NotReadyError('Model serving is not enabled'));
      }

      if (!rbacLoaded) {
        return Promise.reject(new NotReadyError('Fetch is not ready'));
      }

      const getInferenceServices = allowCreate ? listInferenceService : getInferenceServiceContext;

      let inferenceServiceList = await getInferenceServices(
        namespace,
        [
          ...(registeredModelId ? [`${KnownLabels.REGISTERED_MODEL_ID}=${registeredModelId}`] : []),
          ...(modelVersionId ? [`${KnownLabels.MODEL_VERSION_ID}=${modelVersionId}`] : []),
        ].join(','),
        opts,
      );

      if (mrName) {
        inferenceServiceList = inferenceServiceList.filter(
          (inferenceService) =>
            inferenceService.metadata.labels?.[KnownLabels.MODEL_REGISTRY_NAME] === mrName ||
            !inferenceService.metadata.labels?.[KnownLabels.MODEL_REGISTRY_NAME],
        );
      }

      const dashboardInferenceServices = inferenceServiceList.filter(
        ({ metadata: { labels } }) => labels?.[KnownLabels.DASHBOARD_RESOURCE] === 'true',
      );
      return {
        items: dashboardInferenceServices,
        hasNonDashboardItems: inferenceServiceList.length > dashboardInferenceServices.length,
      };
    },
    [
      modelServingEnabled,
      rbacLoaded,
      allowCreate,
      namespace,
      registeredModelId,
      modelVersionId,
      mrName,
    ],
  );

  return useFetch(callback, DEFAULT_LIST_WITH_NON_DASHBOARD_PRESENCE, {
    initialPromisePurity: true,
    ...fetchOptions,
  });
};

export default useInferenceServices;

import * as React from 'react';
import { getInferenceServiceModelState } from '#~/concepts/modelServingKServe/kserveStatusUtils.ts';
import { ModelDeploymentState, ModelServingState } from '#~/pages/modelServing/screens/types';
import useModelPodStatus from '#~/pages/modelServing/useModelPodStatus';
import { FAST_POLL_INTERVAL } from '#~/utilities/const.ts';
import { InferenceServiceKind } from '#~/k8sTypes.ts';
import { getInferenceServiceStoppedStatus } from './utils';

type InferenceServiceStatus = ModelServingState & {
  setIsStarting: (isStarting: boolean) => void;
  setIsStopping: (isStopping: boolean) => void;
  isFailed: boolean;
};

export const useInferenceServiceStatus = (
  inferenceService: InferenceServiceKind,
  refresh?: () => void,
): InferenceServiceStatus => {
  const [isStarting, setIsStarting] = React.useState(false);
  const [isStopping, setIsStopping] = React.useState(false);
  const [pollingInterval, setPollingInterval] = React.useState<NodeJS.Timeout | null>(null);

  const { data: modelPodStatus, refresh: refreshModelPodStatus } = useModelPodStatus(
    inferenceService.metadata.namespace,
    inferenceService.metadata.name,
  );

  // Manual polling when isStopping is true
  React.useEffect(() => {
    if (isStopping) {
      const interval = setInterval(async () => {
        await refreshModelPodStatus();
        if (!modelPodStatus) {
          setIsStopping(false);
        }
      }, FAST_POLL_INTERVAL);

      setPollingInterval(interval);

      return () => {
        clearInterval(interval);
        setPollingInterval(null);
      };
    }
    if (pollingInterval) {
      return () => {
        clearInterval(pollingInterval);
        setPollingInterval(null);
      };
    }
    return undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isStopping, refreshModelPodStatus, refresh, modelPodStatus]);

  // Handle starting state changes
  React.useEffect(() => {
    if (!isStarting) {
      return;
    }

    const currentState = getInferenceServiceModelState(inferenceService);

    if (
      currentState === ModelDeploymentState.LOADING ||
      currentState === ModelDeploymentState.PENDING
    ) {
      setIsStarting(true);
    }

    if ([ModelDeploymentState.LOADED, ModelDeploymentState.FAILED_TO_LOAD].includes(currentState)) {
      setIsStarting(false);
    }
  }, [isStarting, inferenceService]);

  const baseStatus = getInferenceServiceStoppedStatus(inferenceService);
  const isStopped = baseStatus.isStopped && !isStopping;
  const isRunning = baseStatus.isRunning && !isStarting;

  const isNewlyDeployed = React.useMemo(
    () =>
      !inferenceService.status?.modelStatus?.states?.activeModelState &&
      inferenceService.status?.modelStatus?.states?.targetModelState !==
        ModelDeploymentState.FAILED_TO_LOAD &&
      !isStopped &&
      !isStopping,
    [inferenceService.status?.modelStatus?.states, isStopped, isStopping],
  );

  const modelDeploymentState = getInferenceServiceModelState(inferenceService);

  return {
    ...baseStatus,
    isStarting: isStarting || isNewlyDeployed,
    isStopping,
    isStopped,
    isRunning,
    isFailed: modelDeploymentState === ModelDeploymentState.FAILED_TO_LOAD,
    setIsStarting,
    setIsStopping,
  };
};

import * as React from 'react';
import { InferenceServiceKind, PersistentVolumeClaimKind } from '#~/k8sTypes';
import { Connection } from '#~/concepts/connectionTypes/types';
import { ProjectDetailsContext } from '#~/pages/projects/ProjectDetailsContext';
import { getPVCNameFromURI } from '#~/pages/modelServing/screens/projects/utils';

export const useInferenceServicesForConnection = (
  connection?: Connection | PersistentVolumeClaimKind,
): InferenceServiceKind[] => {
  const {
    inferenceServices: {
      data: { items: inferenceServices },
    },
  } = React.useContext(ProjectDetailsContext);
  const connectionName = connection?.metadata.name;
  if (!connection) {
    return [];
  }

  return inferenceServices.filter(
    (inferenceService) =>
      // Known issue: this only works for OCI, S3, and PVC connections
      inferenceService.spec.predictor.model?.storage?.key === connectionName ||
      inferenceService.spec.predictor.imagePullSecrets?.[0]?.name === connectionName ||
      getPVCNameFromURI(inferenceService.spec.predictor.model?.storageUri ?? '') ===
        connection.metadata.name,
  );
};
